/* PWA shell cache: network-first navigation, cache-first static assets. */
(()=>{
  const CACHE="nuvio-shell-v1.0.4";
  self.addEventListener("install",event=>{
    event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(["./","./manifest.webmanifest","./nuvio-icon.svg"]).catch(()=>undefined)));
    self.skipWaiting();
  });
  self.addEventListener("activate",event=>{
    event.waitUntil(Promise.all([
      self.clients.claim(),
      caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith("nuvio-shell-")&&key!==CACHE).map(key=>caches.delete(key))))
    ]));
  });
  self.addEventListener("fetch",event=>{
    const request=event.request;
    if(request.method!=="GET")return;
    const url=new URL(request.url);
    if(url.origin!==self.location.origin||url.pathname.includes("/webtorrent/")||url.pathname.includes("/api/")||url.pathname.endsWith("sw.min.js"))return;
    if(request.mode==="navigate"){
      event.respondWith(fetch(request).then(response=>{
        if(response.ok){const copy=response.clone();void caches.open(CACHE).then(cache=>cache.put("./",copy));}
        return response;
      }).catch(()=>caches.match("./").then(response=>response||Response.error())));
      return;
    }
    if(/\.(?:js|css|svg|png|webp|woff2?)$/i.test(url.pathname)){
      event.respondWith(caches.match(request).then(hit=>hit||fetch(request).then(response=>{
        if(response.ok){const copy=response.clone();void caches.open(CACHE).then(cache=>cache.put(request,copy));}
        return response;
      })));
    }
  });
})();
  
